args.content:
const getPbkdf2Params = (salt: Uint8Array) => ({
  name: 'PBKDF2',
  salt,
  iterations: 100000,
  hash: 'SHA-256',
});

const getAesGcmParams = (iv: Uint8Array) => ({
  name: 'AES-GCM',
  iv,
});

/**
 * Derives a cryptographic key from a password using PBKDF2.
 * @param password The password to use for key derivation.
 * @param salt A cryptographically random salt.
 * @returns A promise that resolves to a CryptoKey.
 */
export const deriveKey = async (password: string, salt: Uint8Array): Promise<CryptoKey> => {
  const passwordBuffer = new TextEncoder().encode(password);
  const baseKey = await crypto.subtle.importKey(
    'raw',
    passwordBuffer,
    { name: 'PBKDF2' },
    false,
    ['deriveKey']
  );
  return crypto.subtle.deriveKey(
    getPbkdf2Params(salt),
    baseKey,
    { name: 'AES-GCM', length: 256 },
    true,
    ['encrypt', 'decrypt']
  );
};

/**
 * Encrypts data using AES-GCM.
 * @param data The data to encrypt.
 * @param key The encryption key.
 * @returns A promise that resolves to an object containing the encrypted data and the initialization vector (iv).
 */
export const encrypt = async (data: ArrayBuffer, key: CryptoKey): Promise<{ encryptedData: ArrayBuffer; iv: Uint8Array }> => {
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const encryptedData = await crypto.subtle.encrypt(
    getAesGcmParams(iv),
    key,
    data
  );
  return { encryptedData, iv };
};

/**
 * Decrypts data using AES-GCM.
 * @param encryptedData The data to decrypt.
 * @param key The decryption key.
 * @param iv The initialization vector used for encryption.
 * @returns A promise that resolves to the decrypted data as an ArrayBuffer.
 */
export const decrypt = async (encryptedData: ArrayBuffer, key: CryptoKey, iv: Uint8Array): Promise<ArrayBuffer> => {
  return crypto.subtle.decrypt(
    getAesGcmParams(iv),
    key,
    encryptedData
  );
};

