'use client';

import React, { useState } from 'react';
import { useAuthStore } from '@/store/useAuthStore';
import { deriveKey } from '@/lib/crypto';

export const Auth = () => {
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const login = useAuthStore((state) => state.login);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (password.length < 8) {
      setError('Password must be at least 8 characters long.');
      return;
    }
    setError('');
    setIsLoading(true);

    try {
      // In a real app, the salt should be unique per user and stored.
      // For this demo, we'll use a static, hardcoded salt.
      // This means the same password will always result in the same key.
      const salt = new TextEncoder().encode('a-very-secret-salt');
      const key = await deriveKey(password, salt);
      login(key);
    } catch (err) {
      console.error(err);
      setError('Failed to derive key. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex flex-col items-center justify-center h-full">
      <div className="w-full max-w-xs p-8 space-y-6 rounded-lg bg-gray-800/20">
        <h1 className="text-2xl font-bold text-center text-matte-white">
          Unlock Vault
        </h1>
        <form onSubmit={handleSubmit} className="space-y-6">
          <div>
            <label
              htmlFor="password"
              className="text-sm font-medium text-gray-400"
            >
              Password
            </label>
            <input
              id="password"
              name="password"
              type="password"
              autoComplete="current-password"
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full px-3 py-2 mt-1 text-matte-white bg-gray-900/50 border border-gray-700 rounded-md shadow-sm focus:outline-none focus:ring-1 focus:ring-gray-500 focus:border-gray-500"
              disabled={isLoading}
            />
          </div>
          {error && <p className="text-sm text-red-500">{error}</p>}
          <div>
            <button
              type="submit"
              className="w-full px-4 py-2 text-sm font-medium text-matte-black bg-matte-white rounded-md shadow-sm hover:bg-gray-200 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-gray-800 focus:ring-white disabled:opacity-50"
              disabled={isLoading}
            >
              {isLoading ? 'Unlocking...' : 'Unlock'}
            </button>
          </div>
        </form>
        <p className="text-xs text-center text-gray-500">
          This is a demo. The same password will always open the same vault.
        </p>
      </div>
    </div>
  );
};

