import { openDB, DBSchema, IDBPDatabase } from 'idb';

const DB_NAME = 'p2p-file-manager';
const DB_VERSION = 1;
const FILES_STORE = 'files';
const DIRS_STORE = 'directories';

export interface FileEntry {
  id: string; // combination of path and name
  name: string;
  path: string; // parent path
  size: number;
  type: string;
  createdAt: Date;
  iv: Uint8Array;
  content: ArrayBuffer; // Encrypted content
}

export interface DirectoryEntry {
  id: string; // combination of path and name
  name:string;
  path: string; // parent path
  createdAt: Date;
}

interface FileSystemDB extends DBSchema {
  [FILES_STORE]: {
    key: string;
    value: FileEntry;
    indexes: { path: string };
  };
  [DIRS_STORE]: {
    key: string;
    value: DirectoryEntry;
    indexes: { path: string };
  };
}

let db: IDBPDatabase<FileSystemDB> | null = null;

const initDB = async () => {
  if (db) return db;

  db = await openDB<FileSystemDB>(DB_NAME, DB_VERSION, {
    upgrade(database) {
      if (!database.objectStoreNames.contains(FILES_STORE)) {
        const fileStore = database.createObjectStore(FILES_STORE, {
          keyPath: 'id',
        });
        fileStore.createIndex('path', 'path', { unique: false });
      }
      if (!database.objectStoreNames.contains(DIRS_STORE)) {
        const dirStore = database.createObjectStore(DIRS_STORE, {
          keyPath: 'id',
        });
        dirStore.createIndex('path', 'path', { unique: false });
      }
    },
  });

  return db;
};

export const getDB = async () => {
  return await initDB();
};

// More functions will be added here (listFiles, createDirectory, etc.)

