// ... (existing code) ...

/**
 * Adds a file to the file system, encrypting it before storing.
 * @param file The file to add.
 * @param path The path to store the file in.
 * @param key The encryption key.
 * @returns A promise that resolves when the file is added.
 */
export const addFile = async (file: File, path: string, key: CryptoKey): Promise<void> => {
  const db = await getDB();
  const id = `${path}${file.name}`;

  const existingFile = await db.get(FILES_STORE, id);
  if (existingFile) {
    throw new Error(`File '${file.name}' already exists in '${path}'`);
  }

  const content = await file.arrayBuffer();
  const { encryptedData, iv } = await encrypt(content, key);

  const newFile: FileEntry = {
    id,
    name: file.name,
    path,
    size: file.size,
    type: file.type,
    createdAt: new Date(),
    iv,
    content: encryptedData,
  };

  await db.add(FILES_STORE, newFile);
};

/**
 * Deletes a file from the file system.
 * @param id The id of the file to delete.
 * @returns A promise that resolves when the file is deleted.
 */
export const deleteFile = async (id: string): Promise<void> => {
  const db = await getDB();
  await db.delete(FILES_STORE, id);
};

/**
 * Recursively deletes a directory and all its contents.
 * @param id The id of the directory to delete.
 * @returns A promise that resolves when the directory and its contents are deleted.
 */
export const deleteDirectoryRec = async (id: string): Promise<void> => {
    const db = await getDB();
    const items = await listDirectory(id);

    for (const item of items) {
        if ('content' in item) { // It's a FileEntry
            await deleteFile(item.id);
        } else { // It's a DirectoryEntry
            await deleteDirectoryRec(item.id);
        }
    }

    await db.delete(DIRS_STORE, id);
};

