'use client';

import React, { useState, useEffect, useCallback } from 'react';
import { useAuthStore } from '@/store/useAuthStore';
import {
  listDirectory,
  createDirectory,
  addFile,
  FileEntry,
  DirectoryEntry,
} from '@/lib/fs';
import { Folder, File, Upload, ArrowLeft } from 'lucide-react';

type FilesystemItem = (FileEntry | DirectoryEntry) & { type: 'file' | 'folder' };

export const FileManager = () => {
  const { cryptoKey, logout } = useAuthStore();
  const [currentPath, setCurrentPath] = useState('/');
  const [items, setItems] = useState<FilesystemItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [newFolderName, setNewFolderName] = useState('');

  const loadItems = useCallback(async () => {
    if (!cryptoKey) return;
    setIsLoading(true);
    setError('');
    try {
      const dirItems = await listDirectory(currentPath);
      const typedItems: FilesystemItem[] = dirItems.map((item) => ({
        ...item,
        type: 'content' in item ? 'file' : 'folder',
      }));
      setItems(typedItems);
    } catch (err) {
      console.error(err);
      setError('Failed to load directory contents.');
    } finally {
      setIsLoading(false);
    }
  }, [currentPath, cryptoKey]);

  useEffect(() => {
    loadItems();
  }, [loadItems]);

  const handleCreateFolder = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newFolderName.trim() || !cryptoKey) return;
    try {
      await createDirectory(newFolderName.trim(), currentPath);
      setNewFolderName('');
      await loadItems();
    } catch (err: any) {
      setError(err.message || 'Failed to create directory.');
    }
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files || e.target.files.length === 0 || !cryptoKey) return;
    const file = e.target.files[0];
    try {
        await addFile(file, currentPath, cryptoKey);
        await loadItems();
    } catch (err: any) {
        setError(err.message || 'Failed to add file.');
    }
  };

  const handleNavigate = (item: FilesystemItem) => {
    if (item.type === 'folder') {
      setCurrentPath(item.id);
    }
    // TODO: Handle file click (download/view)
  };

  const navigateUp = () => {
    if (currentPath === '/') return;
    const parentPath = currentPath.substring(0, currentPath.lastIndexOf('/', currentPath.length - 2) + 1);
    setCurrentPath(parentPath);
  }

  const getBreadcrumbs = () => {
      const pathParts = currentPath.split('/').filter(p => p);
      const crumbs = [{ name: 'Root', path: '/' }];
      let current = '/';
      for (const part of pathParts) {
          current += `${part}/`;
          crumbs.push({ name: part, path: current });
      }
      return crumbs;
  }

  return (
    <div className="w-full h-full flex flex-col">
      <header className="flex items-center justify-between p-4 border-b border-gray-800">
        <h1 className="text-xl font-bold">File Manager</h1>
        <div className="flex items-center gap-4">
            <label htmlFor="file-upload" className="cursor-pointer flex items-center gap-2 px-3 py-2 text-sm font-medium text-matte-white bg-gray-800/50 border border-gray-700 rounded-md hover:bg-gray-700">
                <Upload size={16} />
                <span>Upload</span>
            </label>
            <input id="file-upload" type="file" className="hidden" onChange={handleFileChange} />
            <button
              onClick={logout}
              className="px-4 py-2 text-sm font-medium text-matte-white bg-gray-800/50 border border-gray-700 rounded-md hover:bg-gray-700 focus:outline-none"
            >
              Lock
            </button>
        </div>
      </header>

      <div className="p-4 flex-grow overflow-y-auto">
        <div className="flex items-center justify-between mb-4">
             <nav className="flex items-center text-sm text-gray-400">
                {currentPath !== '/' && (
                    <button onClick={navigateUp} className="p-1 rounded-md hover:bg-gray-800/50 mr-2">
                        <ArrowLeft size={16} />
                    </button>
                )}
                {getBreadcrumbs().map((crumb, i) => (
                    <React.Fragment key={crumb.path}>
                        <span
                            className={`cursor-pointer ${i === getBreadcrumbs().length - 1 ? 'text-matte-white' : 'hover:underline'}`}
                            onClick={() => setCurrentPath(crumb.path)}
                        >
                            {crumb.name}
                        </span>
                        {i < getBreadcrumbs().length - 1 && <span className="mx-2">/</span>}
                    </React.Fragment>
                ))}
            </nav>
        </div>

        <form onSubmit={handleCreateFolder} className="flex gap-2 mb-4">
          <input
            type="text"
            value={newFolderName}
            onChange={(e) => setNewFolderName(e.target.value)}
            placeholder="New folder name..."
            className="flex-grow px-3 py-2 text-matte-white bg-gray-900/50 border border-gray-700 rounded-md focus:outline-none focus:ring-1 focus:ring-gray-500"
          />
          <button
            type="submit"
            className="px-4 py-2 text-sm font-medium text-matte-black bg-matte-white rounded-md disabled:opacity-50"
            disabled={!newFolderName.trim()}
          >
            Create
          </button>
        </form>

