  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [newFolderName, setNewFolderName] = useState('');

  const loadItems = useCallback(async () => {
    if (!cryptoKey) return;
    setIsLoading(true);
    setError('');
    try {
      const dirItems = await listDirectory(currentPath);
      const typedItems: FilesystemItem[] = dirItems.map((item) => ({
        ...item,
        type: 'content' in item ? 'file' : 'folder',
      }));
      setItems(typedItems);
    } catch (err) {
      console.error(err);
      setError('Failed to load directory contents.');
    } finally {
      setIsLoading(false);
    }
  }, [currentPath, cryptoKey]);

  useEffect(() => {
    loadItems();
  }, [loadItems]);

  const handleCreateFolder = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newFolderName.trim() || !cryptoKey) return;
    try {
      await createDirectory(newFolderName.trim(), currentPath);
      setNewFolderName('');
      await loadItems();
    } catch (err: any) {
      setError(err.message || 'Failed to create directory.');
    }
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files || e.target.files.length === 0 || !cryptoKey) return;
    const file = e.target.files[0];
    try {
      await addFile(file, currentPath, cryptoKey);
      await loadItems();
    } catch (err: any) {
      setError(err.message || 'Failed to add file.');
    }
  };

  const handleNavigate = (item: FilesystemItem) => {
    if (item.type === 'folder') {
      setCurrentPath(item.id);
    } else {
      handleFileDownload(item as FileEntry);
    }
  };

