        throw new Error('File not found in the database.');
      }

      const decryptedContent = await decrypt(fileFromDb.content, cryptoKey, fileFromDb.iv);
      const blob = new Blob([decryptedContent], { type: file.type });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = file.name;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    } catch (err: any) {
      setError(err.message || 'Failed to download and decrypt file.');
    }
  };

