          >
            Lock
          </button>
        </div>
      </header>

      <div className="p-4 flex-grow overflow-y-auto">
        <div className="flex items-center justify-between mb-4">
          <nav className="flex items-center text-sm text-gray-400">
            {currentPath !== '/' && (
              <button
                onClick={navigateUp}
                className="p-1 rounded-md hover:bg-gray-800/50 mr-2"
              >
                <ArrowLeft size={16} />
              </button>
            )}
            {getBreadcrumbs().map((crumb, i) => (
              <React.Fragment key={crumb.path}>
                <span
                  className={`cursor-pointer ${
                    i === getBreadcrumbs().length - 1
                      ? 'text-matte-white'
                      : 'hover:underline'
                  }`}
                  onClick={() => setCurrentPath(crumb.path)}
                >
                  {crumb.name}
                </span>
                {i < getBreadcrumbs().length - 1 && (
                  <span className="mx-2">/</span>
                )}
              </React.Fragment>
            ))}
          </nav>
        </div>

        <form onSubmit={handleCreateFolder} className="flex gap-2 mb-4">
          <input
            type="text"
            value={newFolderName}
            onChange={(e) => setNewFolderName(e.target.value)}
            placeholder="New folder name..."
            className="flex-grow px-3 py-2 text-matte-white bg-gray-900/50 border border-gray-700 rounded-md focus:outline-none focus:ring-1 focus:ring-gray-500"
          />
          <button
            type="submit"
            className="px-4 py-2 text-sm font-medium text-matte-black bg-matte-white rounded-md disabled:opacity-50"
            disabled={!newFolderName.trim()}
          >
            Create
          </button>
        </form>

        {error && <p className="text-red-500 mb-4">{error}</p>}

        {isLoading ? (
          <p>Loading...</p>
