          <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4">
            {items.map((item) => (
              <div
                key={item.id}
                className="group relative flex flex-col items-center p-4 rounded-lg cursor-pointer hover:bg-gray-800/50"
                onClick={() => handleNavigate(item)}
              >
                <button 
                  className="absolute top-1 right-1 p-1 rounded-full bg-gray-700/50 text-gray-400 opacity-0 group-hover:opacity-100 hover:bg-red-500/50 hover:text-white transition-opacity"
                  onClick={(e) => {
                      e.stopPropagation();
                      handleDeleteItem(item);
                  }}
                  title={`Delete ${item.name}`}
                >
                    <Trash2 size={14}/>
                </button>
                {item.type === 'folder' ? (
                  <Folder className="w-16 h-16 text-sky-400" />
                ) : (
                  <File className="w-16 h-16 text-gray-400" />
                )}
                <span
                  className="mt-2 text-sm text-center truncate w-full"
                  title={item.name}
                >
                  {item.name}
                </span>
              </div>
            ))}
            {items.length === 0 && !isLoading && (
