import { create } from 'zustand';
import Peer, { DataConnection } from 'peerjs';

interface PeerState {
  peer: Peer | null;
  peerId: string;
  connection: DataConnection | null;
  isConnected: boolean;
  initializePeer: () => void;
  connectToPeer: (remoteId: string) => void;
  disconnect: () => void;
}

export const usePeerStore = create<PeerState>((set, get) => ({
  peer: null,
  peerId: '',
  connection: null,
  isConnected: false,
  initializePeer: () => {
    // Avoid re-initializing
    if (get().peer) return;

    const peer = new Peer();

    peer.on('open', (id) => {
      console.log('My peer ID is: ' + id);
      set({ peer, peerId: id });
    });

    peer.on('connection', (conn) => {
      console.log('Incoming connection from', conn.peer);
      set({ connection: conn, isConnected: true });
    });

    peer.on('disconnected', () => {
      console.log('Peer disconnected.');
      set({ isConnected: false, connection: null });
    });

    peer.on('error', (err) => {
        console.error('PeerJS error:', err);
    });
  },
  connectToPeer: (remoteId) => {
    const { peer } = get();
    if (!peer) {
        console.error('Peer is not initialized.');
        return;
    }

    console.log('Connecting to', remoteId);
    const conn = peer.connect(remoteId);

    conn.on('open', () => {
        console.log('Connection established with', remoteId);
        set({ connection: conn, isConnected: true });
    });

    conn.on('error', (err) => {
        console.error('Connection error:', err);
    });
  },
  disconnect: () => {
    get().connection?.close();
    set({ connection: null, isConnected: false });
  },
}));

'use client';

import React, { useEffect, useState } from 'react';
import { usePeerStore } from '@/store/usePeerStore';
import { Copy, Share2 } from 'lucide-react';

export const PeerManager = () => {
  const { peerId, initializePeer, connectToPeer, isConnected, disconnect } = usePeerStore();
  const [remoteId, setRemoteId] = useState('');

  useEffect(() => {
    initializePeer();
  }, [initializePeer]);

  const handleConnect = (e: React.FormEvent) => {
    e.preventDefault();
    if (remoteId.trim()) {
      connectToPeer(remoteId.trim());
    }
  };

  const handleCopyId = () => {
    navigator.clipboard.writeText(peerId).then(() => {
        alert('Peer ID copied to clipboard!');
    }, (err) => {
        console.error('Could not copy text: ', err);
    });
  }

  return (
    <div className="p-4 border-t border-gray-800">
      <h2 className="text-lg font-bold mb-2 flex items-center gap-2">
        <Share2 size={20} />
        <span>P2P Sharing</span>
      </h2>
      <div className="space-y-4">
        <div className="flex items-center gap-2">
            <p className="font-mono text-sm p-2 rounded-md bg-gray-900/70 border border-gray-700">
                Your ID: {peerId || 'Initializing...'}
            </p>
            <button
                onClick={handleCopyId}
                disabled={!peerId}
                className="p-2 rounded-md bg-gray-800/50 hover:bg-gray-700 disabled:opacity-50 disabled:cursor-not-allowed"
                title="Copy ID"
            >
                <Copy size={16} />
            </button>
        </div>

        {isConnected ? (
             <div className="flex items-center gap-2">
                <p className="text-green-500">Connected to a peer.</p>
                <button
                    onClick={disconnect}
                    className="px-3 py-1 text-sm bg-red-500/80 rounded-md hover:bg-red-600"
                >
                    Disconnect
                </button>
            </div>
        ) : (
            <form onSubmit={handleConnect} className="flex items-center gap-2">
              <input
                type="text"
                value={remoteId}
                onChange={(e) => setRemoteId(e.target.value)}
                placeholder="Enter remote Peer ID"
                className="flex-grow px-3 py-2 text-sm text-matte-white bg-gray-900/50 border border-gray-700 rounded-md focus:outline-none focus:ring-1 focus:ring-gray-500"
              />
              <button
                type="submit"
                className="px-4 py-2 text-sm font-medium text-matte-black bg-matte-white rounded-md disabled:opacity-50"
                disabled={!remoteId.trim()}
              >
                Connect
              </button>
            </form>
        )}
      </div>
    </div>
  );
};

