            htmlFor="file-upload"
            className="cursor-pointer flex items-center gap-2 px-3 py-2 text-sm font-medium text-matte-white bg-gray-800/50 border border-gray-700 rounded-md hover:bg-gray-700"
          >
            <Upload size={16} />
            <span>Upload</span>
          </label>
          <input
            id="file-upload"
            type="file"
            className="hidden"
            onChange={handleFileChange}
          />
          <button
            onClick={logout}
            className="px-4 py-2 text-sm font-medium text-matte-white bg-gray-800/50 border border-gray-700 rounded-md hover:bg-gray-700 focus:outline-none"
          >
            Lock
          </button>
        </div>
      </header>

      <div className="p-4 flex-grow overflow-y-auto">
        <div className="flex items-center justify-between mb-4">
          <nav className="flex items-center text-sm text-gray-400">
            {currentPath !== '/' && (
              <button
                onClick={navigateUp}
                className="p-1 rounded-md hover:bg-gray-800/50 mr-2"
              >
                <ArrowLeft size={16} />
              </button>
            )}
            {getBreadcrumbs().map((crumb, i) => (
              <React.Fragment key={crumb.path}>
                <span
                  className={`cursor-pointer ${
                    i === getBreadcrumbs().length - 1
                      ? 'text-matte-white'
                      : 'hover:underline'
                  }`}
                  onClick={() => setCurrentPath(crumb.path)}
                >
                  {crumb.name}
                </span>
                {i < getBreadcrumbs().length - 1 && (
                  <span className="mx-2">/</span>
                )}
              </React.Fragment>
            ))}
          </nav>
        </div>

        <form onSubmit={handleCreateFolder} className="flex gap-2 mb-4">
          <input
            type="text"
            value={newFolderName}
            onChange={(e) => setNewFolderName(e.target.value)}
            placeholder="New folder name..."
            className="flex-grow px-3 py-2 text-matte-white bg-gray-900/50 border border-gray-700 rounded-md focus:outline-none focus:ring-1 focus:ring-gray-500"
          />
          <button
            type="submit"
            className="px-4 py-2 text-sm font-medium text-matte-black bg-matte-white rounded-md disabled:opacity-50"
            disabled={!newFolderName.trim()}
          >
            Create
          </button>
        </form>

        {error && <p className="text-red-500 mb-4">{error}</p>}

        {isLoading ? (
          <p>Loading...</p>
        ) : (
          <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4">
            {items.map((item) => (
              <div
                key={item.id}
                className="group relative flex flex-col items-center p-4 rounded-lg cursor-pointer hover:bg-gray-800/50"
                onClick={() => handleNavigate(item)}
              >
                <button 
                  className="absolute top-1 right-1 p-1 rounded-full bg-gray-700/50 text-gray-400 opacity-0 group-hover:opacity-100 hover:bg-red-500/50 hover:text-white transition-opacity"
                  onClick={(e) => {
                      e.stopPropagation();
                      handleDeleteItem(item);
                  }}
                  title={`Delete ${item.name}`}
                >
                    <Trash2 size={14}/>
                </button>
                {item.type === 'folder' ? (
                  <Folder className="w-16 h-16 text-sky-400" />
                ) : (
                  <File className="w-16 h-16 text-gray-400" />
                )}
                <span
                  className="mt-2 text-sm text-center truncate w-full"
                  title={item.name}
                >
                  {item.name}
                </span>
              </div>
            ))}
            {items.length === 0 && !isLoading && (
              <p className="text-gray-500 col-span-full text-center">
                This folder is empty.
              </p>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

